def handle_errors(fn=None, *, public=False):
    def wrapper(req):
        if not public:
            claims = verify_request(req)  # auth BEFORE handler
        return handler(req)
    except HttpError as e:
        return e.as_response()
    except Exception:
        return generic_500()  # never leak internals

def test_served_tables_no_credentials():
    for table in SERVED_TABLES:
        cols = column_names(table)
        assert not [c for c in cols if 'assword' in c]
# Opposite: tables WITH credentials have no route
